const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-118.423217, 34.770153]);
  const roi = point.buffer(300);
  const targetDate = ee.Date('2020-04-14');
  const dateRange = ee.DateRange(targetDate.advance(-15, 'day'), targetDate.advance(15, 'day'));

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(roi)
    .filterDate(dateRange.start(), dateRange.end())
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const colSize = collection.size().getInfo();
  console.log(`Landsat 8 images found: ${colSize}`);

  if (colSize === 0) {
    // Try Landsat 9 as fallback
    collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(dateRange.start(), dateRange.end())
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    const col9Size = collection.size().getInfo();
    console.log(`Landsat 9 images found: ${col9Size}`);

    if (col9Size === 0) {
      console.log('No images found in date range.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Cloud masking and get closest image
  function maskL8sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);
    const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
    return image.addBands(opticalBands, null, true)
      .updateMask(qaMask)
      .updateMask(saturationMask);
  }

  const image = collection.map(maskL8sr)
    .sort('CLOUD_COVER')
    .first();

  // Check valid pixels
  const countResult = image.select('SR_B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  });

  const pixelCount = countResult.get('SR_B4').getInfo();
  console.log(`Valid pixels after masking: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation - Compute NDWI, NDVI, and reflectance values
  const nir = image.select('SR_B5');
  const green = image.select('SR_B3');
  const red = image.select('SR_B4');

  const ndwi = green.subtract(nir).divide(green.add(nir)).rename('NDWI');
  const ndvi = nir.subtract(red).divide(nir.add(red)).rename('NDVI');

  const stats = image.addBands([ndwi, ndvi]).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  });

  const ndwiVal = stats.get('NDWI').getInfo();
  const ndviVal = stats.get('NDVI').getInfo();
  const nirVal = stats.get('SR_B5').getInfo();
  const redVal = stats.get('SR_B4').getInfo();

  // 5. Validation & Final Answer
  console.log(`NDWI: ${ndwiVal !== null ? ndwiVal.toFixed(3) : 'null'}`);
  console.log(`NDVI: ${ndviVal !== null ? ndviVal.toFixed(3) : 'null'}`);
  console.log(`NIR: ${nirVal !== null ? nirVal.toFixed(3) : 'null'}`);
  console.log(`Red: ${redVal !== null ? redVal.toFixed(3) : 'null'}`);

  if (ndwiVal === null || ndviVal === null || nirVal === null) {
    console.log('Calculation failed - null values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Solar farm: Low NDWI (not water), moderate NDVI (not dense vegetation), reflective surface
  // Water pond: High NDWI (> 0.2), low NIR, negative or very low NDVI
  if (ndwiVal > 0.2) {
    console.log('High NDWI indicates water pond.');
    console.log('<answer>B</answer>');
  } else if (ndwiVal < 0 && ndviVal < 0.4 && nirVal > 0.1) {
    console.log('Low NDWI, moderate NDVI/NIR indicates solar farm.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Ambiguous - defaulting to water pond.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
